"from bs4 import BeautifulSoup\n\nwith open('tests/workday/Systems Software Engineer - New College Grad 2026.htm', 'r', encoding='utf-8', errors='ignore') as f:\n    soup = BeautifulSoup(f.read(), 'html.parser')\n\ninputs = soup.find_all('input', {'data-automation-id': lambda x: x and 'datesection' in x.lower()})\nfor inp in inputs:\n    print(f\"Date input: id='{inp.get('id')}', aid='{inp.get('data-automation-id')}', aria-label='{inp.get('aria-label')}', aria-valuenow='{inp.get('aria-valuenow')}', role='{inp.get('role')}', parent_id='{inp.parent.get('id') if inp.parent else None}'\")\n"